package zone.moddev.mc.ironagearchitecture.probe;

import java.util.*;
import java.nio.file.*;
import net.minecraft.block.state.IBlockState;
import net.minecraft.entity.player.*;
import net.minecraft.init.*;
import net.minecraft.item.*;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.server.MinecraftServer;
import net.minecraft.util.*;
import net.minecraft.util.math.*;
import net.minecraft.world.WorldServer;
import net.minecraftforge.common.util.*;
import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;
import net.minecraftforge.fml.common.gameevent.TickEvent;
import zone.moddev.mc.ironagearchitecture.*;
import zone.moddev.mc.ironagearchitecture.roof.*;

/** Actual survival construction, local rework and window operations on a disposable server. */
public final class RoofDesignProbe {
    private final WorldServer world;private final MinecraftServer server;private final FakePlayer player;
    private ArchitectWorkbench.Desk desk;private int phase,ticks;private long changes;
    private final Map<String,Object> result=new LinkedHashMap<>();private Map<Long,RoofCell> before;private Map<String,Integer> total;
    private BlockPos preserved;private RoofCell preservedCell;
    private RoofDesignProbe(WorldServer w,MinecraftServer s){world=w;server=s;player=FakePlayerFactory.getMinecraft(w);if(player.connection==null)player.connection=new net.minecraft.network.NetHandlerPlayServer(s,new net.minecraft.network.NetworkManager(net.minecraft.network.EnumPacketDirection.SERVERBOUND),player);player.capabilities.isCreativeMode=false;player.setPosition(1030,100,1030);}
    public static void start(WorldServer w,MinecraftServer s){net.minecraftforge.fml.common.FMLCommonHandler.instance().bus().register(new RoofDesignProbe(w,s));}
    private static void require(boolean c,String s){if(!c)throw new IllegalStateException(s);}
    private void supply(RoofDesignConstruction.Quote q){for(ItemStack s:q.additions.list()){int need=Math.max(0,s.stackSize-desk.count(s.getItem(),s.getMetadata()));if(need>0){ItemStack add=s.copy();add.stackSize=need;desk.give(add);}}}
    private Map<String,Integer> quantities(){Map<String,Integer> out=new TreeMap<>();Set<String> ids=new HashSet<>();for(RoofCell c:RoofData.get(world).owned(world,desk.drawing).values())for(RoofPart p:c.parts)if(ids.add(p.id)){ItemStack s=RoofMaterials.item(p);if(s!=null)out.merge(RoofMaterials.key(s),1,Integer::sum);}for(int i=0;i<27;i++){ItemStack s=desk.getStackInSlot(i);if(s!=null)out.merge(RoofMaterials.key(s),s.stackSize,Integer::sum);}if(desk.job!=null)for(ItemStack s:desk.job.escrow.list())out.merge(RoofMaterials.key(s),s.stackSize,Integer::sum);return out;}
    @SubscribeEvent public void tick(TickEvent.ServerTickEvent e){if(e.phase!=TickEvent.Phase.END||phase==99)return;try{ticks++;require(ticks<2400,"Roof design timeout in phase "+phase);long delta=RoofConstruction.changes-changes;changes=RoofConstruction.changes;require(delta<=16,"shared construction cell cap");
        if(phase==0){
            if(Boolean.getBoolean("iaa.roofDesignReload")){desk=(ArchitectWorkbench.Desk)world.getTileEntity(new BlockPos(1004,81,1005));require(desk!=null,"saved bench");RoofPlan p=desk.drawing;RoofPlan saved=RoofData.get(world).find(desk.getPos().down());require(p!=null&&saved!=null&&p.id.equals(saved.id)&&p.version==2,"saved drawing version");for(long key:p.cells.keySet()){BlockPos at=BlockPos.fromLong(key);world.getChunkFromBlockCoords(at);RoofCell c=RoofData.get(world).at(world,at);require(p.cells.get(key).equals(c),"saved designed profile "+at);}result.put("reload",true);finish();return;}
            desk=WorkbenchProbe.floor(world,1000,1000,8,11,0);for(int x=999;x<=1008;x++){world.setBlockState(new BlockPos(x,80,999),ArchitectureBlocks.SMART_COB.getDefaultState(),2);world.setBlockState(new BlockPos(x,80,1011),ArchitectureBlocks.SMART_COB.getDefaultState(),2);}for(int z=1000;z<=1010;z++){world.setBlockState(new BlockPos(999,80,z),ArchitectureBlocks.SMART_COB.getDefaultState(),2);world.setBlockState(new BlockPos(1008,80,z),ArchitectureBlocks.SMART_COB.getDefaultState(),2);}world.setBlockState(new BlockPos(1003,81,999),ArchitectureBlocks.findWindow("oak",0,false,true,false).getDefaultState(),2);world.setBlockState(new BlockPos(1005,81,999),ArchitectureBlocks.SMART_COB.getDefaultState(),2);RoofConstruction.detect(desk);desk.drawing.alongX=false;desk.drawing.frame=1;require(desk.drawing.wallInset==1,"inset wall detection");RoofFeature g=new RoofFeature();g.id=1;g.type=RoofFeature.GABLE;g.u=1000;g.v=1004;g.cover=3;desk.drawing.features.add(g);RoofFeature win=new RoofFeature();win.id=2;win.type=RoofFeature.WINDOW;win.u=1006;win.v=1008;win.width=1;desk.drawing.features.add(win);RoofPlanner.solve(desk.drawing);require(desk.drawing.valid(),desk.drawing.error);RoofData.get(world).draft(desk.drawing);RoofDesignConstruction.Quote q=RoofDesignConstruction.quote(desk,desk.drawing,player);require(q.error.isEmpty(),q.error);require(!RoofConstruction.start(desk,player),"insufficient materials refuse without writing");supply(q);total=quantities();require(RoofConstruction.start(desk,player),desk.status);phase=1;
        }else if(phase==1&&!desk.active){require(total.equals(quantities()),"first construction conserves all supplied materials");result.put("initialCells",desk.drawing.cells.size());result.put("initialMaterials",total);testGables();testWindows();testWindowMatrix();testClipboard();preserveCover();before=RoofData.get(world).owned(world,desk.drawing);desk.drawing.features.removeIf(f->f.id==1);desk.drawing.gableFill[1]=5;RoofPlanner.solve(desk.drawing);RoofDesignConstruction.Quote q=RoofDesignConstruction.quote(desk,desk.drawing,player);require(q.error.isEmpty(),q.error);require(q.reuse.units()>0,"local rework reuses materials");require(!q.remove.contains(preserved.toLong())&&!q.place.contains(preserved.toLong()),"distant covered section is outside rework");supply(q);total=quantities();require(RoofConstruction.start(desk,player),desk.status);phase=2;
        }else if(phase==2&&desk.index>12){RoofConstruction.cancel(desk);require(total.equals(quantities()),"cancellation conserves removed and reserved materials");result.put("cancelConservation",true);RoofPlanner.solve(desk.drawing);RoofDesignConstruction.Quote q=RoofDesignConstruction.quote(desk,desk.drawing,player);require(q.error.isEmpty(),q.error);supply(q);total=quantities();require(RoofConstruction.start(desk,player),desk.status);phase=3;
        }else if(phase==3&&desk.index>20){NBTTagCompound tag=desk.writeToNBT(new NBTTagCompound());ArchitectWorkbench.Desk replacement=new ArchitectWorkbench.Desk();replacement.readFromNBT(tag);world.setTileEntity(desk.getPos(),replacement);desk=replacement;desk.onLoad();phase=4;
        }else if(phase==4&&!desk.active){require(total.equals(quantities()),"resumed rework conserves materials");require(preservedCell.equals(RoofData.get(world).at(world,preserved)),"distant covering remains intact");for(int x=999;x<=1008;x++)require(world.getBlockState(new BlockPos(x,80,999)).getBlock()==ArchitectureBlocks.SMART_COB,"walls untouched");require(world.getBlockState(new BlockPos(1003,81,999)).getBlock()==ArchitectureBlocks.findWindow("oak",0,false,true,false),"existing gable window retained");require(world.getBlockState(new BlockPos(1005,81,999)).getBlock()==ArchitectureBlocks.SMART_COB,"existing gable block retained");result.put("gableMaterialRework",true);result.put("localRework",true);result.put("savedActiveJob",true);result.put("frameCells",RoofData.get(world).owned(world,desk.drawing).size());world.saveAllChunks(true,null);finish();}
    }catch(Throwable failure){failure.printStackTrace();if(desk!=null){result.put("jobStatus",desk.status);result.put("jobIndex",desk.index);result.put("jobTotal",desk.operations.size());result.put("benchInvalid",desk.isInvalid());}result.put("passed",false);result.put("error",failure.toString());write();server.initiateShutdown();}}
    private void testGables(){
        require(desk.drawing.gableMaterial[0]==0&&desk.drawing.gableMaterial[1]==0,"raw cob matches the lower wall course");
        require(!desk.drawing.cells.containsKey(new BlockPos(1003,81,999).toLong()),"existing gable window excluded from construction");
        require(!desk.drawing.cells.containsKey(new BlockPos(1005,81,999).toLong()),"existing gable wall excluded from construction");
        BlockPos at=new BlockPos(1001,82,999);RoofCell c=RoofData.get(world).at(world,at);require(c!=null,"solid gable above the wall");
        player.setLocationAndAngles(1001.5,82.5-player.getEyeHeight(),997,0,0);RoofPart target=RoofDesignInteraction.target(world,at,player);require(target!=null&&RoofGables.part(target)&&target.kind==RoofPart.WALL,"gable ray targets its paid panel: "+(target==null?"none":target.id+"/"+target.kind)+" eyes="+zone.moddev.mc.ironagearchitecture.block.SmartThatchBlock.eyes(player)+" look="+zone.moddev.mc.ironagearchitecture.block.SmartThatchBlock.look(player)+" parts="+c.parts.stream().map(a->a.id+Arrays.toString(a.data)).collect(java.util.stream.Collectors.joining(";")));
        ItemStack canonical=RoofMaterials.item(target);int before=0;for(int i=0;i<player.inventory.getSizeInventory();i++){ItemStack a=player.inventory.getStackInSlot(i);if(a!=null&&a.isItemEqual(canonical))before+=a.stackSize;}
        require(RoofDesignInteraction.mine(world,at,player),"mine the gable panel");int after=0;for(int i=0;i<player.inventory.getSizeInventory();i++){ItemStack a=player.inventory.getStackInSlot(i);if(a!=null&&a.isItemEqual(canonical))after+=a.stackSize;}require(after==before+1,"gable mining returns one canonical material");
        for(int i=0;i<player.inventory.getSizeInventory();i++){ItemStack a=player.inventory.getStackInSlot(i);if(a!=null&&a.isItemEqual(canonical)){desk.give(player.inventory.decrStackSize(i,1));break;}}
        require(total.equals(quantities()),"mining does not multiply material");player.setPosition(998,90,998);result.put("gableInfillAndMining",true);
    }
    private void testWindows(){Map<String,RoofWindow> units=new TreeMap<>();for(RoofCell c:RoofData.get(world).owned(world,desk.drawing).values())for(RoofWindow w:c.windows)units.putIfAbsent(w.id,w);require(units.size()>=2,"both window kinds");for(RoofWindow w:units.values()){RoofCell c=RoofData.get(world).at(world,w.owner);require(RoofWindowController.set(world,c,w,true,false,player,true),"window opens "+w.id);RoofCell open=RoofData.get(world).at(world,w.owner);RoofWindow now=open.windows.stream().filter(a->a.id.equals(w.id)).findFirst().get();require(now.open,"saved open state");require(RoofWindowController.set(world,open,now,false,false,player,true),"window closes "+w.id);}RoofWindow rooflight=units.get("window:2");require(RoofWindowController.set(world,RoofData.get(world).at(world,rooflight.owner),rooflight,true,false,player,false),"leave distant rooflight open for local rework");result.put("openableWindowKinds",2);}
    private RoofWindow owner(RoofWindow w){RoofCell c=RoofData.get(world).at(world,w.owner);for(RoofWindow n:c.windows)if(n.id.equals(w.id))return n;throw new IllegalStateException("Window root lost");}
    private void testWindowMatrix(){int count=0;for(int pitch:new int[]{16,32,64})for(EnumFacing face:EnumFacing.HORIZONTALS){BlockPos at=new BlockPos(1103+count*16,120,1055);RoofPlan p=new RoofPlan();p.minX=at.getX()-2;p.maxX=at.getX()+3;p.minZ=at.getZ()-2;p.maxZ=at.getZ()+3;p.floorY=119;RoofData.get(world).savePlan(p);RoofWindow n=new RoofWindow("window:test",at,0,0,0,8,pitch,count%24,0,face,false,false,false,false);Map<Long,RoofCell> cells=RoofWindowGeometry.layout(p.id,Collections.emptyMap(),Collections.singleton(n));for(BlockPos a:RoofWindowGeometry.sweepCandidates(n))world.getChunkFromBlockCoords(a);RoofConstruction.changing=true;try{for(Map.Entry<Long,RoofCell> e:cells.entrySet())RoofDesignInteraction.write(world,BlockPos.fromLong(e.getKey()),e.getValue());}finally{RoofConstruction.changing=false;}
        for(int m=0;m<16;m++)require(ArchitectureBlocks.ROOF_WINDOW.getMetaFromState(ArchitectureBlocks.ROOF_WINDOW.getStateFromMeta(m))==m,"roof window metadata");
        RoofCell saved=RoofData.get(world).at(world,at);List<RoofPart> blockedParts=new ArrayList<>(saved.parts);blockedParts.add(new RoofPart("test-obstruction",at,RoofPart.TIMBER,0,new int[]{0,32,0,32,0,0,32,0}));RoofData.get(world).put(world,at,new RoofCell(p.id,at,blockedParts,saved.windows));require(!RoofWindowController.set(world,RoofData.get(world).at(world,at),n,true,false,player,false),"obstructed rooflight is unchanged");require(!owner(n).open,"obstruction rollback");RoofData.get(world).put(world,at,saved);require(RoofWindowController.set(world,RoofData.get(world).at(world,at),n,true,false,player,false),"matrix opening");require(owner(n).open,"matrix open profile");require(RoofWindowController.set(world,RoofData.get(world).at(world,at),owner(n),false,false,player,false),"matrix closing");
        BlockPos power=at.offset(face.rotateY());require(world.isAirBlock(power),"power fixture clear");world.setBlockState(power,Blocks.REDSTONE_BLOCK.getDefaultState(),3);RoofWindowController.neighbor(world,at);require(owner(n).open&&owner(n).powered,"power transition opens");require(RoofWindowController.toggle(world,at,n.id,player),"manual powered override");require(!owner(n).open&&owner(n).powered,"manual state persists with power");RoofWindowController.neighbor(world,at);require(!owner(n).open,"unchanged power preserves hand operation");world.setBlockToAir(power);RoofWindowController.neighbor(world,at);require(!owner(n).powered,"falling power transition");
        require(RoofWindowController.set(world,RoofData.get(world).at(world,at),owner(n),true,false,player,false),"open for helper cleanup");BlockPos helper=null;for(BlockPos a:RoofWindowGeometry.candidates(owner(n)))if(!a.equals(at)&&RoofData.get(world).at(world,a)!=null){helper=a;break;}require(helper!=null,"window helper fixture");world.setBlockState(helper,Blocks.STONE.getDefaultState(),3);require(world.getBlockState(helper).getBlock()==Blocks.STONE,"forced replacement remains");RoofCell root=RoofData.get(world).at(world,at);require(root==null||root.windows.isEmpty(),"forced helper replacement cleans owner");count++;
    }result.put("rooflightFacingPitchCases",count);result.put("windowMetadataStates",16);result.put("powerAndHelperCleanup",true);}
    private void testClipboard(){ItemStack stack=new ItemStack(ArchitectureBlocks.ROOF_CLIPBOARD);RoofClipboardItem.bind(stack,desk.drawing,0);player.setHeldItem(EnumHand.MAIN_HAND,stack);RoofPlan p=RoofDrafts.read(world,desk.drawing.id);int old=p.base;p.base++;p=RoofDrafts.accept(world,player,p);require(p.base==old+1,"clipboard accepted");p=RoofDrafts.undo(world,player,p.id,false);require(p.base==old,"draft undo");p=RoofDrafts.undo(world,player,p.id,true);require(p.base==old+1,"draft redo");p=RoofDrafts.undo(world,player,p.id,false);desk.drawing=p;player.setHeldItem(EnumHand.MAIN_HAND,null);result.put("clipboardUndoRedo",true);}
    private void preserveCover(){for(Map.Entry<Long,RoofCell> e:RoofData.get(world).owned(world,desk.drawing).entrySet()){BlockPos at=BlockPos.fromLong(e.getKey());if(at.getZ()!=1000)continue;for(RoofPart p:e.getValue().parts)if(p.kind==RoofPart.COVER&&p.material==0){require(RoofDesignInteraction.change(world,e.getValue(),p,p.withMaterial(1),player),"fit distant covering");preserved=at;preservedCell=RoofData.get(world).at(world,at);return;}}throw new IllegalStateException("No comparison covering");}
    private void finish(){phase=99;result.put("passed",true);result.put("maxWorkMs",RoofConstruction.maxWorkNanos/1e6);result.put("runtimeSha256",System.getProperty("iaa.runtimeSha256"));write();server.initiateShutdown();}
    private void write(){try{Files.write(Paths.get(System.getProperty("iaa.receipt","roof-design-receipt.json")),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(result).getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(Exception e){throw new RuntimeException(e);}}
}
